const fs=require('node:fs');
const V=m=>{console.error('W1_VIOLATION: '+m);process.exit(1)};
const H=m=>{console.error('W1_HARNESS_ERROR: '+m);process.exit(2)};
try{
 const files=['src/application/generate-localization-report.usecase.ts','src/application/evaluate-compliance-rules.usecase.ts','server/services/complianceRuleEngine.ts'];
 const pattern=/distanceToWater\w*\s*(?:\?\?|\|\|)\s*200\b|distanceToWater\w*\s*:\s*number\s*=\s*200\b|distanceForCompliance\s*(?:\?\?|\|\|)\s*200\b/;
 const hits=[];
 for(const f of files){
  if(!fs.existsSync(f))H('expected production file missing on this tree: '+f);
  const src=fs.readFileSync(f,'utf8');
  if(pattern.test(src))hits.push(f);
 }
 if(hits.length===0)H('positive control failed: base_sha does not carry the known legacy fallback text in any of: '+files.join(', '));
 console.log('W1_FALLBACK_PRESENT: '+hits.join(', '));
 process.exit(1);
}catch(e){H('unexpected: '+(e&&e.stack?e.stack:e))}

