try {

const mod = await import('./server/services/complianceRuleEngine.ts');
if (typeof mod.evaluateComplianceRules !== 'function') H('evaluateComplianceRules not found on the checked-out tree');
const result = mod.evaluateComplianceRules([], [], {}, [], null);
if (!result || !Array.isArray(result.restrictions)) H('unexpected return shape from evaluateComplianceRules: ' + JSON.stringify(result));
if (!result.restrictions.includes('Strandskydd')) H('positive control failed: base_sha did not fabricate Strandskydd from an explicit null distance (expected the pre-fix null-coercion behavior)');
console.log('W1_FALLBACK_FABRICATED: ' + JSON.stringify(result.restrictions));
process.exit(1);

} catch (e) { H('unexpected: ' + (e && e.stack ? e.stack : e)); }

